// Created: 2026-08-22

// The site names external packages by exact install string. Those strings are
// promises: a docs link to a package or command that does not exist is worse
// than no link, because an agent will confidently run it and get a 404.
//
// This is not hypothetical. The CLI was deliberately kept OUT of the site until
// the first publish landed, precisely because npm 11 had silently stripped both
// `bin` entries and the "published" package would have installed cleanly with no
// commands (see packages/cli/tests/package-publish.test.ts). These assertions
// keep the site's claim tied to the package that actually ships, without a
// network call: they compare against packages/cli/package.json, the same
// manifest npm publishes.

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { DEVELOPER_RESOURCES } from "@/lib/developer-resources";

const cliPkg = JSON.parse(
	readFileSync(resolve(__dirname, "../../../packages/cli/package.json"), "utf8"),
) as { name: string; bin?: Record<string, string> };

const llmsTxt = readFileSync(
	resolve(__dirname, "../app/llms.txt/route.ts"),
	"utf8",
);

describe("the site's CLI claim matches the package that ships", () => {
	const entry = DEVELOPER_RESOURCES.find((r) =>
		r.href.includes("npmjs.com/package/"),
	);

	it("the developer hub links the CLI on npm", () => {
		expect(entry, "no npm package entry in DEVELOPER_RESOURCES").toBeDefined();
	});

	it("links the exact package name from packages/cli/package.json", () => {
		expect(entry?.href).toBe(`https://www.npmjs.com/package/${cliPkg.name}`);
	});

	it("only advertises command names the package actually declares", () => {
		// `npx <name>` only resolves to a bin the manifest declares. Advertising
		// `npx ork` while the manifest dropped the `ork` bin is the exact failure
		// npm's publish-time normalizer produced once already.
		const declared = Object.keys(cliPkg.bin ?? {});
		expect(declared.length).toBeGreaterThan(0);
		for (const source of [entry?.desc ?? "", llmsTxt]) {
			for (const advertised of source.matchAll(/npx\s+([a-z][\w-]*)/g)) {
				expect(
					declared,
					`site advertises "npx ${advertised[1]}" but the package declares no such bin`,
				).toContain(advertised[1]);
			}
		}
	});

	it("llms.txt names the same package", () => {
		expect(llmsTxt).toContain(`npmjs.com/package/${cliPkg.name}`);
	});
});
